Level :: struct {
	name: string,
	objects: []Game_Object,
	tiles: []Tiles,
}

generate_level :: proc(name: string) -> Level {
	tiles := generate_tiles(context.allocator)
	objects := generate_objects(tiles, context.allocator)
	return {
		name = strings.clone(name, context.allocator),
		objects = objects,
		tiles = tiles,
	}
}

Result :: struct {
	score: string,
	value: []Game_Object,
	size: []Tiles,
}

score_list :: proc(score: string) -> Result {
	size := total_sum(context.allocator)
	value := item_data(size, context.allocator)
	return {
		score = strings.clone(score, context.allocator),
		value = value,
		size = size,
	}
}

