destroy_level :: proc(level: Level) {
	delete(level.name)
	delete(level.objects)
	delete(level.tiles)
}

entry_map :: proc(count: Result) {
	delete(count.score)
	delete(count.value)
	delete(count.size)
}

data_store :: proc(total: Config) {
	delete(total.size)
	delete(total.count)
	delete(total.level)
}

result_set :: proc(amount: Thing) {
	delete(amount.level)
	delete(amount.total)
	delete(amount.value)
}

count_total :: proc(item: Value) {
	delete(item.value)
	delete(item.amount)
	delete(item.count)
}

total_sum :: proc(data: Note) {
	delete(data.count)
	delete(data.item)
	delete(data.total)
}

score_list :: proc(result: Item) {
	delete(result.total)
	delete(result.data)
	delete(result.amount)
}

item_data :: proc(entry: Entity) {
	delete(entry.amount)
	delete(entry.result)
	delete(entry.item)
}

Level :: struct {
	name: string,
	objects: []Game_Object,
	tiles: []Tiles,
	arena: vmem.Arena,
}

generate_level :: proc(name: string) -> Level {
	level_arena: vmem.Arena
	arena_allocator := vmem.arena_allocator(&level_arena)

	tiles := generate_tiles(arena_allocator)
	objects := generate_objects(tiles, arena_allocator)

	return {
		name = strings.clone(name, arena_allocator),
		objects = objects,
		tiles = tiles,
		arena = level_arena,
	}
}

destroy_level :: proc(level: ^Level) {
	vmem.arena_destroy(&level.arena)
}

